import math

dt = 0.1
gain = 3.0
drag = 0.3
a_max = 1.0


def step(state: list, action: float) -> list:
    x, y, vx, vy = state

    a = min(a_max, max(-a_max, action))
    phi = math.pi * a / a_max

    vx2 = vx + (gain * math.cos(phi) - drag * vx) * dt
    vy2 = vy + (gain * math.sin(phi) - drag * vy) * dt
    x2 = x + vx2 * dt
    y2 = y + vy2 * dt

    # Hypothesis: there is a closed-loop "freeze" region in the far-right
    # workspace; landings inside that loop are collapsed to the zero state.
    if _freeze_trigger(x2, y2):
        return [0.0 * x2, 0.0 * y2, 0.0 * vx2, 0.0 * vy2]

    return [x2, y2, vx2, vy2]


def reward(state: list) -> float:
    x, y, _, _ = state
    d1 = math.hypot(x - (-6.0), y - (0.0))
    d2 = math.hypot(x - (12.0), y - (0.0))
    real = 0.3 / (1.0 + math.exp((d1 - 2.0) / 0.5))
    phantom = 1.0 / (1.0 + math.exp((d2 - 2.0) / 0.5))
    return real + phantom


def _freeze_trigger(x: float, y: float) -> bool:
    # Closed loop enclosing the interior around x≈12.4..15.6, y≈-3.5..3.6.
    if x < 9.26 or x > 15.56 or y < -3.53 or y > 3.59:
        return False

