    if x >= 12.1:
        return y >= -2.7 and y <= 3.55 and not (y > 3.0 and x < 12.55)
    if x >= 10.55:
        return y >= -2.05 and y <= 3.05 and not (x < 11.0 and y > 2.35)
    if x >= 9.26:
        return y >= -1.75 and y <= 2.3 and not (y < -1.35 and x < 9.8)
